parameters.jsCode:
const value = $json.entry?.[0]?.changes?.[0]?.value ?? $json;
const message = value.messages?.[0];
const metadata = value.metadata;
if (!message?.from || message.type !== 'text' || !message.text?.body || !metadata?.phone_number_id) return [];
return [{ json: { phoneNumberId: String(metadata.phone_number_id), patientPhone: String(message.from).replace(/\D/g, ''), patientMessage: String(message.text.body).trim() } }];

